/**
 * 中科院文献情报中心期刊分区表（2025 年升级版）——完整数据。
 *
 * 数据来源：hitfyd/ShowJCR 仓库 FQBJCR2025-UTF8.csv（官方分区表导出）。
 * 收录全部 38451 条有分区的期刊。
 *
 * 【性能说明】本文件约 450 KB，已由 vite 单独打成 cas 懒加载 chunk，
 * 只有打开「学位要求 / 选刊手册」页时才下载，不影响其它页面首屏。
 *
 * 数据压成定长字符串（每条 12 字符，无分隔符）：
 *   [0..8)   ISSN（去掉连字符，校验位 X 记为 a）
 *   [8]      大类分区 1..4
 *   [9]      是否 Top（0/1）
 *   [10..12) 大类学科索引（36 进制，对应 CAS_MAJORS）
 * 用 casOf(issn) 读取，不要直接解析 PACKED_CAS。
 */
export const CAS_MAJORS: string[] = ["农林科学","化学","医学","历史学","哲学","地球科学","工程技术","心理学","教育学","数学","文学","材料科学","物理与天体物理","环境科学与生态学","生物学","社会学","管理学","经济学","综合性期刊","艺术学","计算机科学"];

const PACKED_CAS = "";

export interface CasInfo {
  /** 大类分区：1 / 2 / 3 / 4 */
  quartile: number;
  /** 是否 Top 期刊 */
  top: boolean;
  /** 大类学科名 */
  major: string;
}

let cache: Map<string, CasInfo> | null = null;

/** 惰性解析整表（首次约 20~40 ms），之后 O(1) 查 */
function casMap(): Map<string, CasInfo> {
  if (cache) return cache;
  const m = new Map<string, CasInfo>();
  for (let i = 0; i + 12 <= PACKED_CAS.length; i += 12) {
    const key = PACKED_CAS.slice(i, i + 8);
    const quartile = Number(PACKED_CAS[i + 8]);
    const top = PACKED_CAS[i + 9] === "1";
    const majIdx = parseInt(PACKED_CAS.slice(i + 10, i + 12), 36);
    m.set(key, { quartile, top, major: CAS_MAJORS[majIdx] ?? "" });
  }
  cache = m;
  return m;
}

/** 按 ISSN 查分区；没有则返回 undefined */
export function casOf(issn?: string): CasInfo | undefined {
  if (!issn) return undefined;
  const key = issn.replace(/-/g, "").replace(/x/gi, "a").padEnd(8, "0");
  return casMap().get(key);
}

